namespace ghidra.program.model.data.ISF;

using ghidra.program.model.data;
using ghidra.program.model.data;

public class IsfUtilities {

	public static DataType getBaseDataType(DataType dt) {
		while (dt != null) {
			if (dt is Array) {
				Array array = (Array) dt;
				dt = array.getDataType();
			}
			else if (dt is Pointer) {
				Pointer pointer = (Pointer) dt;
				dt = pointer.getDataType();
			}
			else if (dt is BitFieldDataType) {
				BitFieldDataType bitfieldDt = (BitFieldDataType) dt;
				dt = bitfieldDt.getBaseDataType();
			}
			else {
				break;
			}
		}
		return dt;
	}

	public static DataType getArrayBaseType(Array arrayDt) {
		DataType dataType = arrayDt.getDataType();
		while (dataType is Array) {
			dataType = ((Array) dataType).getDataType();
		}
		return dataType;
	}

	public static DataType getPointerBaseDataType(Pointer p) {
		DataType dt = p.getDataType();
		while (dt is Pointer) {
			dt = ((Pointer) dt).getDataType();
		}
		return dt;
	}

	public static string getKind(DataType dt) {
		if (dt is Array) {
			return "array";
		}
		if (dt is Structure) {
			return "struct";
		}
		if (dt is Union) {
			return "union";
		}
		if (dt is BuiltInDataType) {
			return "base";
		}
		if (dt is Pointer) {
			return "pointer";
		}
		if (dt is Enum) {
			return "enum";
		}
		if (dt is TypeDef) {
			return "typedef";
		}
		if (dt is FunctionDefinition) {
			return "function";
		}
		if (dt is BitFieldDataType) {
			return "bitfield";
		}
		if (dt is DefaultDataType) {
			return "base";
		}
		return "UNKNOWN";
	}

	public static string getBuiltInKind(BuiltInDataType dt) {
		if (dt is AbstractIntegerDataType) {
			return dt.getName();
		}
		if (dt is AbstractFloatDataType) {
			return "float";
		}
		if (dt is AbstractComplexDataType) {
			return "complex";
		}
		if (dt is AbstractStringDataType) {
			return "char"; // "string";
		}
		if (dt is PointerDataType) {
			return "pointer";
		}
		if (dt is VoidDataType) {
			return "void";
		}
		if (dt is Undefined) {
			return "void";
		}
		return "char";
	}

	public static bool isBaseDataType(DataType dt) {
		if (dt is AbstractIntegerDataType) {
			return true;
		}
		if (dt is AbstractFloatDataType) {
			return true;
		}
		if (dt is AbstractComplexDataType) {
			return true;
		}
		if (dt is AbstractStringDataType) {
			return true;
		}
		if (dt is Pointer) {
			return true;
		}
		if (dt is VoidDataType) {
			return true;
		}
		if (dt is Undefined) {
			return true;
		}
		return false;
	}

	public static Integer getLength(DataType dt) {
		return dt.getLength();
	}

	public static string getEndianness(DataType dt) {
		return dt.getDataOrganization().isBigEndian() ? "big" : "little";
	}
	
